//! State-schema DATA over actual recorded raw-source loans. This module never
//! mints CODE completion; only a host-owned exhausted traversal can publish it.
use crate::{state_schema_data::{self as schema,Schema},state_schema_policy::{self as policy,SchemaView},captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_allow_annotations::Operation,key_policy_control::{self as kc,Control},reactive_raw_policy_pages::RawPolicyPages,lint::Site};
use std::{collections::{BTreeMap,BTreeSet,HashSet},sync::Arc,io};
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn checked(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|oom(b,m))?;poll()?;b.require().map_err(|m|oom(b,m))}
fn final_control<T>(pending:Result<T,Failure>,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<T,Failure>{if matches!(&pending,Err(Failure::Operational(_))){return pending}checked(b,poll)?;pending}
struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
/// Owned policy findings only; no source owner, budget or completion is retained.
pub struct StateSchemaData{sites:Vec<Site>,notes:Vec<String>}
impl StateSchemaData{pub fn sites(&self)->&[Site]{&self.sites}pub fn notes(&self)->&[String]{&self.notes}pub fn metadata(&self)->&'static crate::lint::Meta{&policy::META}pub fn retained_charge(&self)->Option<usize>{let mut n=std::mem::size_of::<Self>().checked_add(self.sites.capacity().checked_mul(std::mem::size_of::<Site>())?)?.checked_add(self.notes.capacity().checked_mul(std::mem::size_of::<String>())?)?;for site in &self.sites{for word in [&site.rule,&site.rel,&site.msg,&site.key,&site.ident]{n=n.checked_add(word.capacity())?;}}for note in &self.notes{n=n.checked_add(note.capacity())?;}Some(n)}pub fn serialize_data<S:serde::Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{use serde::ser::SerializeTuple;let mut rows=serializer.serialize_tuple(2)?;rows.serialize_element(&self.sites)?;rows.serialize_element(&self.notes)?;rows.end()}}
struct Facts{schema:Schema,declared:BTreeMap<String,BTreeSet<String>>,usage:HashSet<String>}
fn insert(facts:&mut BTreeMap<String,BTreeSet<String>>,owner:&str,name:&str,work:&mut Operation<'_>)->Result<(),Failure>{work.checkpoint()?;if !facts.contains_key(owner){kc::reserve(work,||Some(2048))?;facts.insert(kc::own(work,owner)?,BTreeSet::new());}let rows=facts.get_mut(owner).expect("actual ownership presence owner");if !rows.contains(name){kc::reserve(work,||Some(2048))?;rows.insert(kc::own(work,name)?);}Ok(())}
/// Same ancestor set/order as schema::chain, using original borrowed path slices
/// for canonical source paths. Compatibility fallback formats only noncanonical
/// DATA, never constructs a source file or a semantic parent graph.
fn chain<C:Control>(subject:&str,c:&mut C,emit:&mut dyn FnMut(&str,&mut C)->Result<(),C::Error>)->Result<(),C::Error>{let text=if subject.starts_with('/')&&!subject.starts_with("//")&&!subject.ends_with('/') {std::borrow::Cow::Borrowed(subject)}else{std::borrow::Cow::Owned(kc::format(c,format_args!("/{}",subject.trim_matches('/')))?) };let tail=&text[1..];let first=tail.split('/').next().unwrap_or("");let implicit:&[&str]=match first{"obj"|"mob"=>&["/datum","/atom","/atom/movable"],"turf"|"area"=>&["/datum","/atom"],"atom"=>&["/datum"],_=>&[]};for path in implicit{c.checkpoint()?;emit(path,c)?;}for(index,_)in tail.match_indices('/'){c.checkpoint()?;emit(&text[..index+1],c)?;}c.checkpoint()?;emit(&text,c)}
impl<'work> SchemaView<Operation<'work>> for Facts{
 fn visit_safe_types(&self,c:&mut Operation<'work>,emit:&mut dyn FnMut(&str,&mut Operation<'work>)->Result<(),Failure>)->Result<usize,Failure>{let mut all=BTreeSet::new();for path in self.schema.decls.keys().chain(self.schema.latent.keys()){c.checkpoint()?;if !all.contains(path.as_str()){kc::reserve(c,||Some(2048))?;all.insert(path.as_str());}}let mut count=0usize;for t in all{c.checkpoint()?;let mut value=false;chain(t,c,&mut|a,_|{if let Some(current)=self.schema.latent.get(a){value=*current}Ok(())})?;if value{count=count.checked_add(1).ok_or_else(||c.overflow())?;emit(t,c)?;}}Ok(count)}
 fn visit_chain(&self,subject:&str,c:&mut Operation<'work>,emit:&mut dyn FnMut(&str,&mut Operation<'work>)->Result<(),Failure>)->Result<(),Failure>{chain(subject,c,emit)}
 fn variables(&self,owner:&str,c:&mut Operation<'work>,visit:&mut dyn FnMut(policy::Variable<'_>,&mut Operation<'work>)->Result<(),Failure>)->Result<(),Failure>{if let Some(vars)=self.schema.decls.get(owner){for v in vars{c.checkpoint()?;visit(policy::Variable{name:&v.name,vtype:&v.vtype,path:&v.path,line:v.line,is_list:v.is_list,saved:v.saved(),holds_ref:v.holds_ref(),registry:v.registry(&self.schema.registry)},c)?;}}Ok(())}
 fn has_codec(&self,name:&str,subject:&str,c:&mut Operation<'work>)->Result<bool,Failure>{let mut found=false;chain(subject,c,&mut|a,_|{found|=self.schema.codecs.get(a).is_some_and(|keys|keys.contains(name));Ok(())})?;Ok(found)}
 fn has_kind(&self,owner:&str,name:&str,c:&mut Operation<'work>)->Result<bool,Failure>{let mut found=false;crate::raw_ownership_policy::visit_parents_using(owner,c,&mut|a,_|{found|=self.declared.get(a).is_some_and(|keys|keys.contains(name));Ok(())})?;Ok(found||self.usage.contains(name))}
}
/// Two fields of original OwnershipKinds are projected to presence because the
/// unique state-schema judge only asks is_some(). First OWN/REL choice and DME
/// marker ordering cannot affect that boolean; no include-order receipt is made.
pub fn collect_from_pages(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<StateSchemaData,Failure>{checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let keep=&phase.budget;let pending=(||{let mut work=Operation{budget:keep,poll};let mut facts=Facts{schema:Schema::default(),declared:BTreeMap::new(),usage:HashSet::new()};kc::reserve(&mut work,||Some(4096))?;let entry=schema::ownership_entry_pattern().map_err(|error|Failure::Unsupported(error.to_string()))?;
 let complete=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(keep);let pending=(||{checked(local,poll)?;views.code()?;let file=views.source_file()?;let raw=file.raw().text.as_str();let code=file.code();let mut temporary=Operation{budget:local,poll};schema::parse_file_using(relative,code,&mut facts.schema.decls,&mut facts.schema.latent,&mut work,&mut temporary)?;schema::parse_codec_keys_file_using(raw,&mut facts.schema.codecs,&mut work,&mut temporary)?;
 if relative==schema::REGISTRY_FILE{kc::reserve(&mut temporary,||crate::raw_ownership_policy::REGISTRY.capture_group_count().checked_mul(4*std::mem::size_of::<Option<(usize,usize)>>())?.checked_add(128))?;for line in raw.split('\n'){temporary.checkpoint()?;if let Some(m)=crate::raw_ownership_policy::REGISTRY.captures(line){kc::row(&mut work,&mut facts.schema.registry)?;facts.schema.registry.push(kc::own(&mut work,m.s(1))?);}}}
 kc::reserve(&mut temporary,||crate::raw_ownership_policy::ACCESSOR.capture_group_count().checked_mul(4*std::mem::size_of::<Option<(usize,usize)>>())?.checked_add(128))?;for m in crate::raw_ownership_policy::ACCESSOR.captures_iter(raw){temporary.checkpoint()?;if !facts.usage.contains(m.s(3)){kc::reserve(&mut work,||Some(2048))?;facts.usage.insert(kc::own(&mut work,m.s(3))?);}}
 // The unchanged shared event scanner may allocate temporary parsed events;
 // those remain in this real FileScope. Only declared-key presence moves out.
 let width=raw.split('\n').try_fold(0usize,|width,line|{temporary.checkpoint()?;Ok::<_,Failure>(width.max(line.len()))})?;kc::reserve(&mut temporary,||width.checked_mul(12)?.checked_add(8192))?;let mut actual=None;let event_result=crate::raw_ownership_policy::visit_file_events(relative,file.raw(),code,|event|{if let crate::raw_ownership_policy::IdxEv::Decl{owner,name,..}=event{if let Err(error)=insert(&mut facts.declared,&owner,&name,&mut work){actual=Some(error);return Err("typed state-schema event admission stopped".into())}}Ok(())});if let Some(error)=actual{return Err(error)}event_result.map_err(Failure::Unsupported)?;
 let mut rows=Vec::new();let mut count=0;crate::captured_marker_rows::collect_file_funded(relative,views.marker()?,local,local,&["CAPABILITIES"],false,true,false,&mut rows,&mut count,&mut||{checked(local,poll)})?;kc::reserve(&mut temporary,||entry.captures_len().checked_mul(4*std::mem::size_of::<Option<(usize,usize)>>())?.checked_add(128))?;for marker in rows{temporary.checkpoint()?;let Some(owner)=marker.args.first()else{continue};let mut actual=None;schema::visit_ownership_entries(&entry,&marker.body,|name,_|{if actual.is_none(){if let Err(error)=insert(&mut facts.declared,owner,name,&mut work){actual=Some(error)}}});if let Some(error)=actual{return Err(error)}}Ok(true)})();final_control(pending,local,poll)})?;if !complete{return Err("state-schema source stopped before CODE_DM EOF".into())}kc::row(&mut work,&mut facts.schema.registry)?;facts.schema.registry.push(kc::own(&mut work,"/decl")?);
 let mut data=StateSchemaData{sites:Vec::new(),notes:Vec::new()};policy::judge_using(&facts,&mut work,&mut|relative,line,message,c|{kc::row(c,&mut data.sites)?;data.sites.push(Site{rule:kc::own(c,"schema")?,rel:kc::own(c,relative)?,line:u32::try_from(line).map_err(|_|c.overflow())?,msg:message,key:String::new(),ident:String::new()});Ok(())},&mut|message,c|{kc::row(c,&mut data.notes)?;data.notes.push(message);Ok(())})?;checked(keep,poll)?;Ok(data)})();let pending=final_control(pending,keep,poll);let pending=match pending{Ok(data)=>{let bytes=data.retained_charge().ok_or_else(||oom(root,"state-schema returned capacity overflow"))?;match root.charge(bytes).map_err(|m|oom(root,m)){Ok(())=>Ok(data),Err(actual)=>{drop(data);Err(actual)}}},Err(actual)=>Err(actual)};phase.ok=pending.is_ok();drop(phase);final_control(pending,root,poll)}
